IDLE_HELP = [
    "# idlelib — 11166 عنصراً عربياً",
]

_IDLE_TOKEN = re.compile(
    r"(?P<dot>\.)?"
    r"(?P<word>(?!\d)[\w\u064B-\u065F\u0670]+)"
    r"(?P<open>\s*\()?"
)

USER_NAMES = set()


def _idle_replace(match):
    dot = match.group("dot")
    word = match.group("word")
    open_paren = match.group("open")
    if word in USER_NAMES:
        return match.group(0)
    if dot:
        if open_paren and word in IDLE_METHODS:
            return "." + IDLE_METHODS[word] + open_paren
        if word in IDLE_PROPS:
            return "." + IDLE_PROPS[word]
        return match.group(0)
    if word in IDLE_CONSTS:
        return IDLE_CONSTS[word]
    if word in IDLE_FUNCS:
        return IDLE_FUNCS[word] + (open_paren or "")
    return match.group(0)


def IDLE_SUBSTITUTE(text):
    """يترجم كلمات المكتبة في نص واحد ويُرجع المترجم."""
    if not text:
        return text
    return _IDLE_TOKEN.sub(_idle_replace, text)
